#!/usr/bin/env python3
"""fix_features_32: writes the finished Quality review frontend files in full (repairs a partly applied round 30/31). Safe to run twice."""
import os, base64, zlib, json
FILES = json.loads('{"frontend/src/components/enh/ReviewWorkspace.tsx": "", "frontend/src/components/NotificationBanner.tsx": "", "frontend/src/components/layout/AppLayout.tsx": "", "frontend/src/pages/Quality.tsx": "", "frontend/src/api/client.ts": ""}')
root = os.getcwd()
if not os.path.isdir(os.path.join(root, "frontend", "src")):
    raise SystemExit("Run this from the repo root (the folder that has frontend/ and backend/).")
for rel, blob in FILES.items():
    data = zlib.decompress(base64.b64decode(blob))
    p = os.path.join(root, rel)
    same = os.path.exists(p) and open(p, "rb").read() == data
    if not same:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        open(p, "wb").write(data)
    print(("already up to date  " if same else "written             ") + rel)
